@_mutmut_mutated(mutants_x_add_building__mutmut)
def add_building(
    db: Session,
    project_version_id: UUID,
    builder_profile_id: UUID,
    name: str,
    building_number: str | None,
    floors: int | None,
) -> Building:
    version = db.scalar(
        select(ProjectVersion).where(
            ProjectVersion.id == project_version_id
        )
    )

    if version is None:
        raise ValueError("Project version not found")

    if version.status != "DRAFT":
        raise ValueError(
            "Buildings can only be added to a DRAFT version"
        )

    project = db.scalar(
        select(Project).where(
            Project.id == version.project_id,
            Project.builder_id == builder_profile_id,
            Project.deleted_at.is_(None),
        )
    )

    if project is None:
        raise ValueError(
            "Builder does not own this project"
        )

    building = Building(
        project_version_id=version.id,
        name=name,
        building_number=building_number,
        floors=floors,
    )

    db.add(building)
    db.commit()
    db.refresh(building)

    return building


